    amount NUMERIC(12, 2) NOT NULL, 
    bank_transaction_id VARCHAR(255), 
    payment_date TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
