    CONSTRAINT fk_production_tasks_project FOREIGN KEY(project_id) REFERENCES projects (id)
);

CREATE INDEX ix_production_tasks_id ON production_tasks (id);

CREATE INDEX ix_production_tasks_project_id ON production_tasks (project_id);

